Definition ex_post_v (v : bool) (ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 : word) (F : bvmap 5 word) (fc : bv 32)
    (TL T SP TP : Z) (sbs tbs : list byte) (tlrest trest : list cell) (lo : Z) (m : mem) : machine_state -> Prop :=
  fun ms' => exists t0 t1 t2 a1 a2 a3 a4 a5 a6 a7 t3 t4 t5 t6 m',
    ms' = MS (mkR ra sp gp tp t0 t1 t2 s0 s1 (wz (if v then 1 else 0))
                  a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
             F (ret_pc ra) fc None m' (seg_rom rsegs)
    /\ munch [(lo, bv_unsigned sp)]%Z m m' /\ wmono rsegs m m' /\ mem_inv rsegs m'
    /\ stk rsegs m' lo (bv_unsigned sp)
    /\ rw_cells rsegs m' TL (C8 (wz SP) :: C8 (wz (Z.of_nat (length sbs))) :: tlrest)
    /\ rw_cells rsegs m' T (C8 (wz TP) :: C8 (wz (Z.of_nat (length tbs))) :: trest)
    /\ bytes_at rsegs m' SP sbs /\ bytes_at rsegs m' TP tbs.

Lemma token_list_exists_post_v : forall ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 F fc TL T SP TP sbs tbs tlrest trest lo m,
  token_list_exists_post ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 F fc TL T SP TP sbs tbs tlrest trest lo m
  = ex_post_v (token_list_exists (zbytes sbs) (zbytes tbs)) ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 F fc TL T SP TP sbs tbs tlrest trest lo m.
Proof. intros. reflexivity. Qed.

(* [comment removed for export] *)
Definition ex_ctx (m m1 : mem) (sp s0v s1v s2v rav : word) (TL T SP TP : Z) (sbs tbs : list byte) (tlrest trest : list cell)
    (lo : Z) (j0 : list byte) (ebc itc : list cell) : Prop :=
  rw_cells rsegs m1 (bv_unsigned sp + -160) [CB 8 j0]
  /\ rw_cells rsegs m1 (bv_unsigned sp + -152) ebc
  /\ rw_cells rsegs m1 (bv_unsigned sp + -112) (TokItCells 0 0 (SP + Z.of_nat (length sbs)) (SP + Z.of_nat (length sbs)) (SP + Z.of_nat (length sbs)))
  /\ rw_cells rsegs m1 (bv_unsigned sp + -72) itc
  /\ rw_cells rsegs m1 (bv_unsigned sp + -32) [C8 s2v; C8 s1v; C8 s0v; C8 rav]
  /\ rw_cells rsegs m1 TL (C8 (wz SP) :: C8 (wz (Z.of_nat (length sbs))) :: tlrest)
  /\ rw_cells rsegs m1 T (C8 (wz TP) :: C8 (wz (Z.of_nat (length tbs))) :: trest)
  /\ bytes_at rsegs m1 SP sbs /\ bytes_at rsegs m1 TP tbs
  /\ stk rsegs m1 lo (bv_unsigned sp + -160)
  /\ munch [(lo, bv_unsigned sp)]%Z m m1 /\ wmono rsegs m m1 /\ mem_inv rsegs m1.

Definition ex_pure (sp : word) (TL T SP TP : Z) (sbs tbs : list byte) (tlrest trest : list cell) (lo : Z) : Prop :=
  SP + Z.of_nat (length sbs) < 2^64 /\ TP + Z.of_nat (length tbs) < 2^64
  /\ lo + 160 <= bv_unsigned sp /\ 0xb4000 <= lo
  /\ (bv_unsigned sp <= TL \/ TL + Z.of_nat (cells_size (C8 (wz SP) :: C8 (wz (Z.of_nat (length sbs))) :: tlrest)) <= lo)
  /\ (bv_unsigned sp <= T \/ T + Z.of_nat (cells_size (C8 (wz TP) :: C8 (wz (Z.of_nat (length tbs))) :: trest)) <= lo)
  /\ (bv_unsigned sp <= SP \/ SP + Z.of_nat (length sbs) <= lo)
  /\ (bv_unsigned sp <= TP \/ TP + Z.of_nat (length tbs) <= lo).

Local Ltac open_ectx CTX PURE :=
  lazymatch type of CTX with ex_ctx _ _ ?sp _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ =>
  destruct CTX as (J0 & EB & EA & IT & FRhi & TLC & TC & WS & WT & ST & MU & WM & MI);
  destruct PURE as (SP64 & TP64 & LO & L94 & SEP1 & SEP2 & SEP3 & SEP4);
  pose proof (bytes_at_bound _ _ _ _ WS) as WSB; pose proof (bytes_at_bound _ _ _ _ WT) as WTB;
  pose proof (rw_cells_bound _ _ _ _ TLC) as TLB; cbn [cells_size csize Nat.add length] in TLB, SEP1;
  pose proof (rw_cells_bound _ _ _ _ TC) as TCB; cbn [cells_size csize Nat.add length] in TCB, SEP2;
  pose proof (rw_cells_bound _ _ _ _ EB) as EBB;
  pose proof (bv_unsigned_in_range 64 sp) as SPR; unfold bv_modulus in SPR; change (2 ^ Z.of_N 64) with (2^64) in SPR;
  unfold TokItCells in * end.

Local Ltac ex_rebuild_ctx m sp :=
  try match goal with C : ex_ctx _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ |- _ => clear C end;
  lazymatch goal with |- evt _ _ (MS _ _ _ _ _ ?mx _) =>
  lazymatch goal with
  | J0 : rw_cells _ mx (bv_unsigned sp + -160) [CB 8 ?j0], EB : rw_cells _ mx (bv_unsigned sp + -152) ?ebc,
    EA : rw_cells _ mx (bv_unsigned sp + -112) _, IT : rw_cells _ mx (bv_unsigned sp + -72) ?itc,
    FRhi : rw_cells _ mx (bv_unsigned sp + -32) [C8 ?s2v; C8 ?s1v; C8 ?s0v; C8 ?rav],
    TLC : rw_cells _ mx ?TL (C8 _ :: C8 (_ (Z.of_nat (length ?sbs))) :: ?tlrest),
    TC : rw_cells _ mx ?T (C8 _ :: C8 (_ (Z.of_nat (length ?tbs))) :: ?trest),
    WS : bytes_at _ mx ?SP ?sbs, WT : bytes_at _ mx ?TP ?tbs, ST : stk _ mx ?lo _,
    MU : munch _ m mx, WM : wmono _ m mx, MI : mem_inv _ mx |- _ =>
      let CTX := fresh "CTX" in
      assert (CTX : ex_ctx m mx sp s0v s1v s2v rav TL T SP TP sbs tbs tlrest trest lo j0 ebc itc)
        by (split; [exact J0 | split; [exact EB | split; [exact EA | split; [exact IT | split; [exact FRhi | split; [exact TLC |
            split; [exact TC | split; [exact WS | split; [exact WT | split; [exact ST | split; [exact MU | split; [exact WM | exact MI]]]]]]]]]]]])
  end end.

