Definition ex_cont (Q : machine_state -> Prop) (pc : Z) rax spx gp tp t1 t2 s0 s1 a0 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6
    (F : bvmap 5 word) fc (m1 : mem) : Prop :=
  forall t0' a1' a2' a3' a4' a5' a6' a7',
    evt rsegs Q (MS (mkR rax spx gp tp t0' t1 t2 s0 s1 a0 a1' a2' a3' a4' a5' a6' a7' s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
                    F (Z_to_bv 64 pc) fc None m1 (seg_rom rsegs)).

Lemma ex_slow : forall (k j : nat) (Q : machine_state -> Prop) rax spx gp tp t0 t1 t2 s0 s1 a0 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6
    (F : bvmap 5 word) fc (m1 : mem) (TP VP : Z) (tbs vbs : list byte),
  (length tbs - j = k)%nat -> (j < length tbs)%nat -> length vbs = length tbs ->
  bytes_at rsegs m1 TP tbs -> bytes_at rsegs m1 VP vbs -> TP + Z.of_nat (length tbs) < 2^64 -> VP + Z.of_nat (length vbs) < 2^64 ->
  mem_inv rsegs m1 ->
  (tl_ieqb (skipn j (zbytes tbs)) (skipn j (zbytes vbs)) = true ->
     ex_cont Q 0x3415c rax spx gp tp t1 t2 s0 s1 a0 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6 F fc m1) ->
  (tl_ieqb (skipn j (zbytes tbs)) (skipn j (zbytes vbs)) = false ->
     ex_cont Q 0x34150 rax spx gp tp t1 t2 s0 s1 a0 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6 F fc m1) ->
  evt rsegs Q (MS (mkR rax spx gp tp t0 t1 t2 s0 s1 a0 (wz (Z.of_nat (length tbs) - Z.of_nat j)) (wz (TP + Z.of_nat j)) (wz (VP + Z.of_nat j))
                       a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
                  F (Z_to_bv 64 0x34124) fc None m1 (seg_rom rsegs)).
