Lemma ex_fast : forall (k j : nat) (Q : machine_state -> Prop) rax spx gp tp t0 t1 t2 s0 s1 a0 a1 a2 a3 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6
    (F : bvmap 5 word) fc (m1 : mem) (TP VP : Z) (tbs vbs : list byte),
