Lemma bytes_at_sub : forall m P bs (a n : nat), bytes_at rsegs m P bs -> (a + n <= length bs)%nat ->
  bytes_at rsegs m (P + Z.of_nat a) (firstn n (skipn a bs)).
Proof.
  intros m P bs a n WIN H.
  rewrite <- (firstn_skipn a bs) in WIN. apply bytes_at_app in WIN. destruct WIN as [_ W2].
  rewrite firstn_length_le in W2 by lia.
  rewrite <- (firstn_skipn n (skipn a bs)) in W2. apply bytes_at_app in W2. destruct W2 as [W2 _]. exact W2.
Qed.

Lemma zbytes_firstn : forall n bs, zbytes (firstn n bs) = firstn n (zbytes bs).
Proof. intros n bs. unfold zbytes. rewrite firstn_map. reflexivity. Qed.
